"""Local configuration constructors; these perform no I/O."""
def make_config(workers=1, tags=None, limits=None):
    return {'settings': {'workers': workers, 'tags': list(tags or []), 'limits': dict(limits or {})}, 'plugin': None}

import json, pathlib, unittest
from config_loader import load_config
class Profiles(unittest.TestCase):
    def test_profiles(self):
        for item in json.loads(pathlib.Path('examples/profiles.json').read_text()):
            with self.subTest(expression=item['expression']):
                self.assertEqual(load_config(item['expression']),item['expected'])

"""Reversing transform plugin."""


class Transform:
    name = "acme_reverse"

    def transform(self, text: str) -> str:
        return text[::-1]

"""Uppercasing transform plugin."""


class Transform:
    name = "acme_upper"

    def transform(self, text: str) -> str:
        return text.upper()

